CREATE TABLE departments(dept_id text PRIMARY KEY,dept_name text,is_active integer DEFAULT 1);
CREATE TABLE users(user_id text PRIMARY KEY,role text,dept_id text,employee_id text,status text DEFAULT 'active');
CREATE TABLE employee_profiles(employee_id text PRIMARY KEY,name text,dept_id text REFERENCES departments,status text DEFAULT 'active');
CREATE TABLE employee_dept_posts(employee_id text,dept_id text,post_kind text,is_primary integer DEFAULT 0,revoked_at text,effective_from text,effective_to text,created_at text);
CREATE TABLE facilities(facility_id text PRIMARY KEY,company_name text,business_registration_no text,site_address text,normalized_company_name text,normalized_address text,region_sido text,region_sigungu text,source text,memo text,created_at text,updated_at text,deleted_at text,site_address_verbatim boolean);
CREATE TABLE contracts(contract_id text PRIMARY KEY,facility_id text REFERENCES facilities,owning_dept_id text,deleted_at text);
CREATE TABLE service_participants(contract_id text,employee_id text);
CREATE TABLE permission_templates(template_id text PRIMARY KEY,is_active integer DEFAULT 1);
CREATE TABLE permission_template_grants(grant_id text PRIMARY KEY,template_id text,permission_key text,scope_kind text,scope_dept_id text,effect text);
CREATE TABLE user_permission_assignments(assignment_id text PRIMARY KEY,user_id text,template_id text,scope_override_kind text,scope_override_dept_id text,revoked_at text,effective_from text,effective_to text);
CREATE TABLE sales_projects(project_id text PRIMARY KEY,facility_id text REFERENCES facilities,title text,stage text,owner_employee_id text,owner_dept_id text,contract_id text,service_category text,service_subcategory text,expected_amount numeric,priority text,status text,opened_at text,closed_at text,memo text,created_by text,created_at text,updated_at text);
CREATE TABLE sales_project_members(id bigserial PRIMARY KEY,project_id text REFERENCES sales_projects,employee_id text,role_label text,created_at text,UNIQUE(project_id,employee_id,role_label));
CREATE TABLE sales_activities(activity_id text PRIMARY KEY,project_id text REFERENCES sales_projects,activity_type text,status text,scheduled_at text,ended_at text,occurred_at text,place text,summary text,progress_note text,quote_amount numeric,bid_amount numeric,quotes jsonb,bids jsonb,bid_result text,color text,author_employee_id text,created_by text,created_at text,updated_at text);
CREATE TABLE sales_activity_contacts(activity_id text,person_id integer,UNIQUE(activity_id,person_id));
CREATE TABLE sales_activity_assignees(activity_id text,employee_id text,role_kind text,created_at text,UNIQUE(activity_id,employee_id,role_kind));
CREATE TABLE intel_signals(signal_id text PRIMARY KEY,source text,external_id text,company_name text,report_name text,signal_type text DEFAULT 'new_factory',signal_grade text DEFAULT 'confirmed',summary text,amount numeric,url text,disclosed_at text,facility_id text REFERENCES facilities,industry text,industry_relevance text,match_status text DEFAULT 'unmatched',status text DEFAULT 'new',duplicate_of text,linked_project_id text REFERENCES sales_projects,created_at text,updated_at text);
CREATE TABLE scraper_sources(source_id text PRIMARY KEY,official_provider text,official_config jsonb);
CREATE TABLE intel_source_documents(document_id text PRIMARY KEY,signal_id text,source_id text REFERENCES scraper_sources,current_revision_id text,status text DEFAULT 'available');
CREATE TABLE intel_source_document_revisions(revision_id text PRIMARY KEY,document_id text REFERENCES intel_source_documents,rights_snapshot jsonb);
CREATE TABLE audit_log(id bigserial PRIMARY KEY,actor_user_id text,action text,target_table text,target_id text,before_json jsonb,after_json jsonb,created_at text);
